from langgraph.types import interrupt

def approve_refund(state: dict) -> dict:
    if state["amount"] <= state["limit"]:
        return {"approved": True, "approver": "auto"}
    decision = interrupt({"question": f"Approve refund of {state['amount']}?"})
    return {"approved": decision == "yes", "approver": "human"}

def cost_per_1k(in_tok: int, out_tok: int, p_in: float, p_out: float, hit_rate: float) -> float:
    per_req = (in_tok * p_in + out_tok * p_out) / 1_000_000
    return round(per_req * (1 - hit_rate) * 1000, 2)

print(cost_per_1k(4000, 400, 3.0, 15.0, 0.25))
